"""Compact evidence review from recomputed physical outcomes, never synthetic scores."""
import argparse,json,html,shutil
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True);s=json.loads((a.root/'analysis/SUMMARY.json').read_text())
for name in ['SUMMARY.json','RESULTS.csv']:shutil.copy2(a.root/'analysis'/name,a.out/name)
for name in ['DESIGN_SUMMARY.json','STUDY_MANIFEST.json','REVISION_PROTOCOL.json','REFERENCE_IDENTITY.json','ANCHOR_REVISION.json','WITNESS_VIOLATIONS.json','SOLVER_COMPARISON.json','SOLVER_COMPARISON_V2.json','DEPLOYMENT_BEHAVIOR.json','TERMINAL_OPTION_DIAGNOSTIC.json','OPTION_OCCUPANCY.json','FRONT_ACTION_COUNTS.json','JOINT_PREDECESSOR_COMPARISON.json','OPTION_ENTROPY_DIAGNOSTIC.json','WITNESS_MARGINS.json','FROZEN_COMPARISON.json','MARGIN_PROTOCOL.json','MARGIN_DECISION.json','DISAGREEMENT_PROTOCOL.json','TRAIN_RETENTION_PROTOCOL.json','PAIRED_INTERVALS.json','ENVIRONMENT.json','FINAL_WITNESS_SUPPORT.json','DEPENDENCY_MODELS.json','POSITIVE_OPTION_WINDOWS.json','SOLVER_COMPARISON_FINAL_RECHECK.json']:
 if (a.root/name).exists():shutil.copy2(a.root/name,a.out/name)
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>'for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>'for x in r)+'</tr>'for r in rows)+'</tbody></table></div>'
def score(names):
 return table(['Policy/checkpoint','Native success','Rescue','Regression','Planner calls','Planner seconds'],[[n,f"{s['groups'][n]['success']}/{s['groups'][n]['episodes']}",len(s['groups'][n].get('rescue',[])),len(s['groups'][n].get('regression',[])),s['groups'][n]['planner_calls'],round(s['groups'][n]['planner_seconds'],2)]for n in names])
training=table(['Learner','Own episodes','Own success','Own physics steps','Own decisions','Updates','Own planner calls','Refresh episodes','Solver rejected steps'],[[n,v['own']['episodes'],v['own']['success'],v['own']['steps'],v['own_decisions'],v['updates'],v['own']['planner_calls'],v['refresh']['episodes'],v['projection']['zero_steps']]for n,v in s['training'].items()])
figures=[('LEARNING_CURVES','Actual learning and fixed-checkpoint native deployment'),('PAIR_MECHANISM','Original-reset physical branches under the same frozen continuation'),('ALGORITHM','Reference-bound physical evidence and actual online policy updates'),('FIRST_ITERATION','First actual method iteration: shared-data matched learners'),('WITNESS_TRANSFER','Recorded action margins versus actual native deployment'),('CONFIRMATION','Frozen new-condition rescue and regression')]
gallery=''.join(f'<section><h2>{title}</h2><a href="figures/{name}.pdf">Vector PDF</a><img src="figures/{name}.png"></section>'for name,title in figures if (a.out/'figures'/f'{name}.png').exists())
videos=''
for folder in sorted(a.out.glob('video_*')):
 if not(folder/'ANNOTATED.mp4').exists():continue
 videos+=f'<section><h2>{html.escape(folder.name)}</h2><p>Complete native physical traces visualized as MEASURED_STATE_REPLAY. Rendering adds zero physical episodes and is not a second experiment.</p><video controls preload="metadata" src="{folder.name}/ANNOTATED.mp4"></video><p><a href="{folder.name}/RAW.mp4">Complete RAW</a> · <a href="{folder.name}/SYNC_VIEWER.html">Exact-frame synchronized curves</a> · <a href="{folder.name}/MANIFEST.json">Source SHA</a></p></section>'
dev=sorted(n for n in s['groups']if '@'in n);confirm=sorted(n for n in s['groups']if n.startswith('confirm_'));cost=s['global_unique'];err={}
training_witness=score(sorted(n for n in s['groups'] if n.startswith('training_witness_')))
disagreement=s.get('disagreement')
additional=html.escape(json.dumps(disagreement,ensure_ascii=False,indent=2)) if disagreement else 'Not yet complete'
if disagreement:
 additional=html.escape(json.dumps({k:v for k,v in disagreement.items() if k not in ['positive_pairs','cost']},ensure_ascii=False,indent=2))
for x in cost['errors']:err[str(x['error'])]=err.get(str(x['error']),0)+1
page=f'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARES | Physical continuation and retained policy improvement</title><style>body{{margin:0;background:#edf2f5;color:#173044;font:16px/1.65 system-ui}}main{{max-width:1280px;margin:auto;padding:28px}}section,header{{background:white;padding:26px;margin:18px 0;border-radius:10px}}header{{border-top:6px solid #008c8c}}h1{{font-size:31px;line-height:1.3}}h2{{font-size:23px}}a{{color:#087a93}}img,video{{width:100%;height:auto}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{text-align:left;padding:8px;border-bottom:1px solid #dde6eb}}th{{background:#e7f0f4}}.scroll{{overflow:auto}}.note{{background:#fff2df;border-left:4px solid #b97a34;padding:14px}}.tag{{background:#dceef0;padding:5px 10px;margin-right:8px}}pre{{white-space:pre-wrap}}</style><main>
<header><span class="tag">Native Peg100</span><span class="tag">Actual PhysX interaction</span><span class="tag">No physical robot motion</span><h1>从真实干预后果到可持续的技能策略改进</h1><p>ARES SCI · 2026-11-08 · baseline d4a20b0</p><p>保留强规划器、真实抓持、83维观测和13个后继选择。区分物理动作机会、学习器更新正确性和完整任务收益。</p><p><a href="README.md">研究结论</a> · <a href="METHOD.md">训练机制与修订</a> · <a href="PRIOR_ART.md">最近邻与源码</a> · <a href="SUMMARY.json">复算数据</a> · <a href="RAW_MANIFEST.json">原始归档与SHA</a></p></header>
<section><h2>本轮可证伪问题</h2><p>平均KL接近是否足以保留必要干预？在同一实际执行见证上，软集合模仿与约束参数更新，能否改善完整任务的救回/退化平衡？</p><p class="note">名义继续不是撤销既往修正。selector0是规则chunk，physical0是继续当前队列。投影、KL、SAC、成功BC都是成熟构件；有限记录约束不保证未见物理状态安全。独立方法收益必须由同预算实际结果决定。</p></section>
<section><h2>固定检查点 · 已见开发768400–415</h2><p>救回/退化相对相同初始化10/16。原近似投影的64回合版本是保留的数值停滞诊断，不能与128回合终点混为等预算比较。所有中间检查点均显示。</p>{score(dev)}</section>
<section><h2>冻结的新自然条件 ·768600–631</h2><p>仅显示实际执行结果；空表表示尚未开启。该组是新的开发确认，不是封存测试。两种子共享场景，不能当64个独立任务。历史oldRL/上一轮SAC具有不同训练预算和执行接口，单列参照。</p>{score(confirm)}</section>
<section><h2>真实在线采集与训练成本</h2><p>每个学习臂另使用同一189次初始物理采集；全局只计一次。每臂64回合后按相同16场景/最多两替代动作规则重新采集，合法动作可用性导致实际分支数不同，明确报告。前驱冻结是任务条件化的warm策略，jointSAC单独开放前驱学习。</p>{training}</section><section><h2>训练见证的完整原生重执行</h2><p>预先选定8个原有成功及3个存在已测救回的训练场景；仅验证训练侧保留，不是泛化。</p>{training_witness}</section><section><h2>新增策略分歧采集</h2><p>在新的连续32场景上选择最早可执行分歧边界，按原生初态重执行。该批未供本轮冻结模型训练；与早期循环采样不是同场景随机对照，不主张采集效率优势。</p><pre>{additional}</pre></section>{gallery}{videos}
<section><h2>全局实测成本与边界</h2><p>{cost['episodes']}次实际原生执行，{cost['steps']}物理步，{cost['planner_calls']}次规划调用；累计规划{cost['planner_seconds']:.1f}秒，累计执行{cost['execution_seconds']:.1f}秒。并发后的墙钟时间与这些累计值不同。</p><p>终止/失败记录：{html.escape(str(err))}。HORIZON是原生预算结束记录，不自动等同基础设施崩溃。全部负轨迹保留。</p><p>初始64场景35个warm成功，125条物理配对含4条救回、22条退化、99条平局；有限实测成功并集38/64不是部署分数或全局上限。正例多数已接近终点，不能单凭它们声称解决了长续接学习。</p></section></main></html>'''
(a.out/'REVIEW.html').write_text(page);print(a.out/'REVIEW.html')
